        {...fieldProps}
        ref={useMergedRefs(ref, inputRef)}
        id={id}
        name={isDisabled ? undefined : htmlName}
        type={type}
        {...textEntryTraitAttributes({
          enterKeyHint,
          inputMode,
          autoCapitalize,
          hasAutoCorrect,
